package cl.bolsillo.app;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.util.concurrent.*;
/** Regression checks for cache isolation, async loads and interruptible Material motion. */
final class V16Checks {
 static int checks;static void yes(boolean value,String text)throws Exception{checks++;if(!value)throw new Exception(text);}static void pause(Instrumentation t,int ms)throws Exception{Thread.sleep(ms);t.waitForIdleSync();}
 static void loaded(Instrumentation t,MainActivity a)throws Exception{long until=SystemClock.uptimeMillis()+10000;while((a.data==null||a.dataLoading)&&SystemClock.uptimeMillis()<until)pause(t,50);yes(a.data!=null&&!a.dataLoading,"background snapshot becomes available");pause(t,250);}
 static int run(Instrumentation t,Context c)throws Exception{
  checks=0;Map<String,Object> secure=VisualChecks.preferences(c.getSharedPreferences("secure",0)),settings=VisualChecks.preferences(NativeStore.settings(c)),updates=VisualChecks.preferences(AppUpdates.prefs(c));MainActivity[] host={null};SheetDialog[] choice={null};
  try{
   LocalData.restore(c,VisualChecks.fixture());NativeStore.settings(c).edit().putBoolean("detectionTutorialSeen",true).putBoolean("capture",false).putBoolean("privateScreen",false).putBoolean("alertChanges",false).putBoolean("alertVerifications",false).putString("appearance","dark").putInt("glassIntensity",1).commit();AppUpdates.prefs(c).edit().putLong("attempt",System.currentTimeMillis()).commit();JSONObject copy=LocalData.read(c);String unchanged=copy.toString();copy.getJSONArray("transactions").remove(0);copy.getJSONArray("accounts").getJSONObject(0).put("opening",999999);yes(unchanged.equals(LocalData.read(c).toString()),"read cache never exposes a mutable canonical ledger");JSONObject state=NativeStore.state(c);state.put("not-written","private scratch");yes(!NativeStore.state(c).has("not-written"),"state cache isolates uncommitted caller mutations");
   JSONObject queued=NativeSync.transaction("expense",1234,"bank-mach","","expense-0","Cambio de caché","manual","");NativeStore.enqueue(c,queued);yes(Ledger.find(LocalData.read(c).getJSONArray("transactions"),queued.getString("id"))!=null,"queue write invalidates prepared snapshot immediately");String expected=LocalData.read(c).getJSONArray("transactions").toString();JSONArray detached=NativeStore.inbox(c);detached.put(new JSONObject().put("id","scratch"));yes(NativeStore.inbox(c).length()==0,"inbox projection is detached from encrypted state");
   host[0]=(MainActivity)t.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));MainActivity a=host[0];loaded(t,a);View shell=a.root;FrostedDock dock=a.navigationDock;for(String route:new String[]{"Cuentas","Explorar","Movimientos","Inicio"}){t.runOnMainSync(()->a.navigate(route));pause(t,270);yes(shell==a.root&&dock==a.navigationDock,"navigation retains window and GPU dock for "+route);yes(a.scroll.getAlpha()==1&&a.scroll.getScaleX()==1&&a.scroll.getTranslationX()==0,"transition fully settles for "+route);}yes(expected.equals(LocalData.read(c).getJSONArray("transactions").toString()),"navigation preserves exact movements");View content=a.body;t.runOnMainSync(()->{a.refreshTask.run();a.updateBadge.run();});yes(content==a.body,"redundant data/update callbacks do not rebuild a current page");
   for(int i=0;i<18;i++){final String route=new String[]{"Movimientos","Cuentas","Explorar"}[i%3];t.runOnMainSync(()->a.navigate(route));pause(t,12);}pause(t,400);yes(a.tab.equals("Explorar")&&a.scroll.getAlpha()==1&&a.scroll.getScaleX()==1&&a.scroll.getTranslationX()==0&&PageMotion.animations.isEmpty()&&PageMotion.pending.isEmpty(),"rapid reversals leave no partial frame or orphan animator");
   List<String> labels=new ArrayList<>();for(int i=0;i<300;i++)labels.add("Categoría de prueba "+i);int[] picked={-1};t.runOnMainSync(()->choice[0]=NativeSettings.choose(a,"Selector grande",labels,n->picked[0]=n));pause(t,260);ListView list=VisualChecks.views(choice[0].layout,ListView.class).get(0);yes(list.getChildCount()<15&&list.getCount()==300,"large selector builds visible rows and keeps all 300 options");yes((choice[0].getWindow().getAttributes().flags&WindowManager.LayoutParams.FLAG_BLUR_BEHIND)==0,"sheet does not blur the entire activity behind it");yes(choice[0].getWindow().getAttributes().windowAnimations==R.style.SheetMotion,"sheet uses unified platform window motion");t.runOnMainSync(()->list.setSelection(299));pause(t,160);t.runOnMainSync(()->list.getChildAt(list.getChildCount()-1).performClick());yes(picked[0]==299&&!choice[0].isShowing(),"last virtualized option selects the correct item");choice[0]=null;
   View button=Modern.iconButton(a,"plus","Prueba de pulsación",()->{});t.runOnMainSync(()->{a.body.addView(button,new LinearLayout.LayoutParams(a.dp(52),a.dp(52)));button.setPressed(true);});pause(t,120);yes(button.getScaleX()<1,"press has restrained scale feedback");t.runOnMainSync(()->button.setPressed(false));pause(t,220);yes(button.getScaleX()==1&&button.getScaleY()==1,"cancel or release restores pressed geometry");
   t.runOnMainSync(()->{NativeStore.settings(c).edit().putString("palette","ocean").apply();a.render(false);});pause(t,300);yes(shell!=a.root,"palette change rebuilds the shell when required");NativeStore.settings(c).edit().putString("palette",(String)settings.getOrDefault("palette","prisma")).commit();
   String sources=NativeStore.settings(c).getString("sources","[]");AppPicker.IO.submit(()->{try{Thread.sleep(450);}catch(InterruptedException ignored){}});long[] opening={0};t.runOnMainSync(()->{long start=SystemClock.uptimeMillis();try{AppPicker.show(a);}catch(Exception e){throw new RuntimeException(e);}opening[0]=SystemClock.uptimeMillis()-start;});yes(opening[0]<350,"app chooser opens without waiting for package enumeration");pause(t,280);UiSmoke.shot(t,c,"v16-app-picker");V15Checks.tap(t,"Cancelar");AppPicker.IO.submit(()->{}).get(15,TimeUnit.SECONDS);yes(sources.equals(NativeStore.settings(c).getString("sources","[]")),"cancelled async chooser cannot modify selected sources");
   JSONObject next=NativeSync.transaction("income",4567,"bank-mach","","income-0","Aviso nuevo","manual","");NativeStore.enqueue(c,next);t.runOnMainSync(()->{a.navigate("Movimientos");a.navigate("Cuentas");a.navigate("Explorar");});loaded(t,a);yes(a.tab.equals("Explorar")&&Ledger.find(a.data.getJSONArray("transactions"),next.getString("id"))!=null,"latest route wins while a new ledger snapshot loads");t.runOnMainSync(()->a.navigate("Inicio"));pause(t,500);List<DonutChart> charts=VisualChecks.views(a.body,DonutChart.class);int dormant=0;for(DonutChart chart:charts)if(chart.entrance!=null&&chart.entrance.animation==null)dormant++;yes(dormant>=2,"offscreen charts do not run simultaneous entrance animators");UiSmoke.shot(t,c,"v16-home");
  }finally{if(choice[0]!=null)t.runOnMainSync(()->choice[0].dismiss());if(host[0]!=null)t.runOnMainSync(()->host[0].finish());t.waitForIdleSync();NativeSync.EXEC.submit(()->{}).get(15,TimeUnit.SECONDS);VisualChecks.restore(c.getSharedPreferences("secure",0),secure);VisualChecks.restore(NativeStore.settings(c),settings);VisualChecks.restore(AppUpdates.prefs(c),updates);}return checks;
 }
}
